```sql
alter table public.teams enable row level security;
alter table public.team_members enable row level security;
alter table public.documents enable row level security;

create or replace function public.is_team_member(p_team_id bigint)
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select exists (
    select 1
    from public.team_members tm
    where tm.team_id = p_team_id
      and tm.user_id = auth.uid()
  );
$$;

create or replace function public.is_team_editor(p_team_id bigint)
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select exists (
    select 1
    from public.team_members tm
    where tm.team_id = p_team_id
      and tm.user_id = auth.uid()
      and tm.role = 'editor'
  );
$$;

create or replace function public.documents_guard()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  if new.id is null then
    raise exception 'document id cannot be null';
  end if;

  if new.team_id is null then
    raise exception 'document must belong to a team';
  end if;

  if new.created_by is null then
    raise exception 'document must have a creator';
  end if;

  if new.created_by <> auth.uid() then
    raise exception 'document creator must be the current user';
  end if;

  if new.deleted_at is not null and not public.is_team_member(new.team_id) then
    raise exception 'deleted documents can only be created in teams where the user is a member';
  end if;

  return new;
end;
$$;

create trigger documents_guard
before insert on public.documents
for each row execute function public.documents_guard();

create policy teams_select_members
on public.teams
for select
to authenticated
using (public.is_team_member(id));

create policy team_members_select_own
on public.team_members
for select
to authenticated
using (user_id = auth.uid());

create policy documents_select_team
on public.documents
for select
to authenticated
using (
  public.is_team_member(team_id)
  and deleted_at is null
);

create policy documents_insert_team_editor
on public.documents
for insert
to authenticated
with check (
  public.is_team_editor(team_id)
  and created_by = auth.uid()
  and deleted_at is null
);

create policy documents_update_team_editor
on public.documents
for update
to authenticated
using (
  public.is_team_editor(team_id)
  and deleted_at is null
)
with check (
  public.is_team_editor(team_id)
  and deleted_at is null
);

create policy documents_delete_own
on public.documents
for delete
to authenticated
using (
  created_by = auth.uid()
  and deleted_at is null
);

revoke all on public.teams from anon, authenticated;
revoke all on public.team_members from anon, authenticated;
revoke all on public.documents from anon, authenticated;

revoke all on public.teams from public;
revoke all on public.team_members from public;
revoke all on public.documents from public;

grant select on public.teams to authenticated;
grant select on public.team_members to authenticated;
grant select, insert, update, delete on public.documents to authenticated;

grant all on public.teams to service_role;
grant all on public.team_members to service_role;
grant all on public.documents to service_role;

grant usage, select on sequence public.documents_id_seq to authenticated;
grant usage, select on sequence public.documents_id_seq to service_role;
