alter table public.teams enable row level security;
alter table public.team_members enable row level security;
alter table public.documents enable row level security;

-- Helper: is the current user a member of the given team?
create or replace function public.is_team_member(p_team_id bigint)
returns boolean
language sql
stable
security definer
set search_path = public, pg_temp
as $$
  select exists (
    select 1
    from public.team_members m
    where m.team_id = p_team_id
      and m.user_id = auth.uid()
  );
$$;

-- Helper: is the current user an editor of the given team?
create or replace function public.is_team_editor(p_team_id bigint)
returns boolean
language sql
stable
security definer
set search_path = public, pg_temp
as $$
  select exists (
    select 1
    from public.team_members m
    where m.team_id = p_team_id
      and m.user_id = auth.uid()
      and m.role = 'editor'
  );
$$;

revoke all on function public.is_team_member(bigint) from public;
revoke all on function public.is_team_editor(bigint) from public;
grant execute on function public.is_team_member(bigint) to authenticated;
grant execute on function public.is_team_editor(bigint) to authenticated;

-- R1: users can see the teams they belong to
create policy teams_select on public.teams
  for select
  to authenticated
  using (public.is_team_member(id));

-- R2: users can see their own membership rows only
create policy team_members_select on public.team_members
  for select
  to authenticated
  using (user_id = auth.uid());

-- R3: team members can read the team's non-deleted documents
create policy documents_select on public.documents
  for select
  to authenticated
  using (
    public.is_team_member(team_id)
    and deleted_at is null
  );

-- R4: editors can create documents in their teams, recorded as themselves
create policy documents_insert on public.documents
  for insert
  to authenticated
  with check (
    created_by = auth.uid()
    and public.is_team_editor(team_id)
  );

-- R5: editors can edit any document in their teams, but must stay in their team
create policy documents_update on public.documents
  for update
  to authenticated
  using (
    public.is_team_editor(team_id)
  )
  with check (
    public.is_team_editor(team_id)
  );

-- R6: only the creator can delete a document
create policy documents_delete on public.documents
  for delete
  to authenticated
  using (
    created_by = auth.uid()
  );

-- R7: no policies exist on teams or team_members for insert/update/delete,
-- so users cannot create/change/remove teams or memberships.

-- R8: no policies grant access to anon, so anonymous visitors cannot see or change anything.
