    select 1
    from public.team_members m
    where m.team_id = p_team_id
      and m.user_id = auth.uid()
      and m.role = 'editor'
  );
$$;

create or replace function public.team_member_role(p_team_id bigint)
returns text
language sql
stable
security definer
set search_path = ''
as $$
  select m.role
  from public.team_members m
  where m.team_id = p_team_id
    and m.user_id = auth.uid()
  limit 1;
$$;

-- R1: teams visible only to members
create policy "teams_select_members"
on public.teams
for select
to authenticated
using (public.is_in_team(id));

-- R2: membership rows are per-user; only own rows are visible
create policy "team_members_select_own"
on public.team_members
for select
to authenticated
using (user_id = auth.uid());

