create policy "documents_select_team"
on public.documents
for select
to authenticated
using (
  public.is_in_team(team_id)
  and deleted_at is null
);

-- R4: editors may create documents in their teams, authoring as themselves
create policy "documents_insert_editor"
on public.documents
for insert
to authenticated
with check (
  created_by = auth.uid()
  and public.can_edit_team(team_id)
);

-- R5: editors may edit documents in their teams; the edit can't move the
-- document into a team where the user is not an editor.
create policy "documents_update_editor"
on public.documents
for update
to authenticated
using (
  public.is_in_team(team_id)
  and public.can_edit_team(team_id)
)
with check (
  public.is_in_team(team_id)
  and public.can_edit_team(team_id)
);

-- R6: only the document's creator may delete it
create policy "documents_delete_own"
on public.documents
for delete
to authenticated
using (created_by = auth.uid());

-- R7: teams and memberships are immutable for app users
revoke all on public.teams from anon, authenticated;
revoke all on public.team_members from anon, authenticated;
revoke all on public.documents from anon, authenticated;

grant select on public.teams to authenticated;
grant select on public.team_members to authenticated;
grant select, insert, update, delete on public.documents to authenticated;

