alter table public.accounts enable row level security;
alter table public.files enable row level security;
alter table public.file_shares enable row level security;

create or replace function public.is_file_owner(p_file_id bigint)
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select exists (
    select 1
    from public.files f
    where f.id = p_file_id
      and f.owner_id = auth.uid()
  );
$$;

create or replace function public.is_file_share_valid(p_file_id bigint, p_shared_with uuid)
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select exists (
    select 1
    from public.file_shares s
    where s.file_id = p_file_id
      and s.shared_with = p_shared_with
      and (s.expires_at is null or s.expires_at > now())
  );
$$;

create or replace function public.is_account_suspended()
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select exists (
    select 1
    from public.accounts a
    where a.user_id = auth.uid()
      and a.suspended
  );
$$;

create or replace function public.enforce_file_share_ownership()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  if new.file_id is distinct from old.file_id
     or new.shared_with is distinct from old.shared_with
     or new.can_edit is distinct from old.can_edit
     or new.expires_at is distinct from old.expires_at
  then
    raise exception 'file_shares rows are immutable';
  end if;
  return new;
end;
$$;

create trigger enforce_file_share_ownership
before update on public.file_shares
for each row
execute function public.enforce_file_share_ownership();

create policy accounts_select_own
on public.accounts
for select
to authenticated
using (user_id = auth.uid());

create policy files_select_own_or_shared
on public.files
for select
to authenticated
using (
  owner_id = auth.uid()
  or public.is_file_share_valid(id, auth.uid())
);

create policy files_insert_own
on public.files
for insert
to authenticated
with check (owner_id = auth.uid());

create policy files_update_own
on public.files
for update
to authenticated
using (owner_id = auth.uid())
with check (owner_id = auth.uid());

create policy files_delete_own
on public.files
for delete
to authenticated
using (owner_id = auth.uid());

create policy file_shares_select_own_or_shared
on public.file_shares
for select
to authenticated
using (
  file_id in (
    select f.id
    from public.files f
    where f.owner_id = auth.uid()
  )
  or shared_with = auth.uid()
);

