on public.file_shares
for insert
to authenticated
with check (
  file_id in (
    select f.id
    from public.files f
    where f.owner_id = auth.uid()
  )
  and public.is_file_share_valid(file_id, shared_with)
);

create policy file_shares_update_own
on public.file_shares
for update
to authenticated
using (
  file_id in (
    select f.id
    from public.files f
    where f.owner_id = auth.uid()
  )
