  );
$$;

create or replace function public.invoice_guard()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  if auth.role() = 'service_role' then
    return new;
  end if;

  if new.id is distinct from old.id
     or new.created_by is distinct from old.created_by then
    raise exception 'invoice creator cannot be changed';
  end if;

  if new.status = 'draft' then
    if old.status is distinct from 'draft' then
      raise exception 'only draft invoices can be restored';
    end if;
    return new;
  end if;

  if old.status = 'draft' then
    if new.status is distinct from 'sent' then
      raise exception 'draft invoices can only be sent';
    end if;
    if new.customer is distinct from old.customer
       or new.amount is distinct from old.amount then
      raise exception 'draft customer and amount cannot be changed';
    end if;
    return new;
  end if;

  if old.status = 'sent' then
    if new.status not in ('paid', 'void') then
      raise exception 'sent invoices can only be marked paid or void';
    end if;
    return new;
  end if;

  if old.status in ('paid', 'void') then
    raise exception 'paid and void invoices are immutable';
  end if;

  return new;
end;
$$;

create trigger invoices_guard
before update on public.invoices
for each row execute function public.invoice_guard();

create policy invoices_select on public.invoices
for select to authenticated
using (created_by = auth.uid() or public.is_finance_staff());

create policy invoices_insert on public.invoices
for insert to authenticated
with check (created_by = auth.uid() and status = 'draft');

create policy invoices_update on public.invoices
for update to authenticated
using (
  (created_by = auth.uid() and old.status = 'draft')
  or (public.is_finance_staff() and old.status = 'sent')
)
with check (
  (created_by = auth.uid() and old.status = 'draft' and new.status = 'sent')
  or (public.is_finance_staff() and old.status = 'sent' and new.status in ('paid', 'void'))
);

create policy invoices_delete on public.invoices
for delete to authenticated
using (created_by = auth.uid() and old.status = 'draft');

revoke all on public.finance_staff from anon, authenticated;
grant select on public.finance_staff to authenticated;

revoke all on public.invoices from anon;
grant select, insert, update, delete on public.invoices to authenticated;
grant usage, select on sequence public.invoices_id_seq to authenticated;

revoke all on public.finance_staff from public;
revoke all on public.invoices from public;

grant all on public.finance_staff to service_role;
grant all on public.invoices to service_role;
