create or replace function public.is_reservation_time_passed(p_reservation_id bigint)
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select exists (
    select 1
    from public.reservations r
    where r.id = p_reservation_id
      and r.reserved_for < now()
  );
$$;

create or replace function public.reservations_guard()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  if auth.role() = 'service_role' then
    return new;
  end if;

  if tg_op = 'INSERT' then
    if new.user_id is distinct from auth.uid() then
      raise exception 'reservations can only be booked for yourself';
    end if;
    if new.reserved_for <= now() then
      raise exception 'reservations can only be booked for a time in the future';
    end if;
    if new.status <> 'booked' then
      raise exception 'new reservations must be booked';
    end if;
    return new;
  end if;

  if tg_op = 'UPDATE' then
    if new.user_id is distinct from old.user_id then
      raise exception 'reservations cannot be reassigned';
    end if;
    if new.restaurant_id is distinct from old.restaurant_id then
      raise exception 'reservations cannot be moved to another restaurant';
    end if;
    if new.reserved_for is distinct from old.reserved_for then
      raise exception 'reservation time cannot be changed';
    end if;
    if new.party_size is distinct from old.party_size then
      raise exception 'party size cannot be changed';
    end if;

    if old.status = 'booked' and new.status in ('seated', 'no_show') then
      if not public.is_restaurant_staff(old.restaurant_id) then
        raise exception 'only restaurant staff can change reservation status';
      end if;
      if not public.is_reservation_time_passed(old.id) then
        raise exception 'reservation time must have passed to change status';
      end if;
    end if;

    if old.status <> 'booked' and new.status <> 'booked' then
      raise exception 'only booked reservations can be changed';
    end if;

    return new;
  end if;

  return new;
end;
$$;

