  v_invited_by uuid;
  v_role text;
  v_expires_at timestamptz;
  v_accepted_at timestamptz;
begin
  if auth.uid() is null then
    raise exception 'not authenticated';
  end if;

  select i.org_id, i.email, i.invited_by, i.role, i.expires_at, i.accepted_at
