language sql stable security definer set search_path = ''
as $$
  select auth.jwt() ->> 'role' = 'auditor';
$$;

create function private.stock_guard(
  p_op char(1),
  p_location_id bigint,
  p_sku text,
  p_qty integer
) returns trigger
language plpgsql security definer set search_path = ''
as $$
declare
  v_uid uuid := auth.uid();
  v_is_auditor boolean;
  v_is_staff boolean;
  v_frozen boolean;
begin
  if v_uid is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;

  v_is_auditor := private.is_auditor();
  v_is_staff := private.is_staff(p_location_id);
  v_frozen := private.is_frozen(p_location_id);

  if v_is_auditor then
    if p_op = 'I' then
      raise exception 'auditor cannot add stock' using errcode = '42501';
    elsif p_op = 'U' then
      raise exception 'auditor cannot change stock' using errcode = '42501';
    elsif p_op = 'D' then
      raise exception 'auditor cannot remove stock' using errcode = '42501';
    end if;
    return new;
  end if;

  if p_op = 'I' then
    if not v_is_staff then
      raise exception 'not staff at this location' using errcode = '42501';
    end if;
    if v_frozen then
      raise exception 'location is frozen' using errcode = '42501';
    end if;
    return new;
  end if;

  if p_op = 'U' then
    if not v_is_staff then
      raise exception 'not staff at this location' using errcode = '42501';
    end if;
    if v_frozen then
      raise exception 'location is frozen' using errcode = '42501';
    end if;
    if p_location_id is distinct from new.location_id
       or p_sku is distinct from new.sku then
      raise exception 'location or sku cannot be changed' using errcode = '42501';
    end if;
    return new;
  end if;

  if p_op = 'D' then
    if not v_is_staff then
      raise exception 'not staff at this location' using errcode = '42501';
    end if;
    if v_frozen then
      raise exception 'location is frozen' using errcode = '42501';
    end if;
    return new;
  end if;

  raise exception 'unknown stock operation' using errcode = '42501';
end;
$$;

create trigger stock_guard_insert
before insert on public.stock
for each row execute function private.stock_guard('I', new.location_id, new.sku, new.qty);

create trigger stock_guard_update
before update on public.stock
for each row execute function private.stock_guard('U', new.location_id, new.sku, new.qty);

create trigger stock_guard_delete
before delete on public.stock
for each row execute function private.stock_guard('D', old.location_id, old.sku, old.qty);

