as $$
begin
  if new.id is distinct from old.id then
    raise exception 'issue id cannot be changed';
  end if;

  if old.is_confidential = true
     and new.is_confidential is distinct from old.is_confidential then
    if new.is_confidential = false
       and public.can_read_issue(new.id) then
      return new;
    end if;
  end if;

