     or new.project_id is distinct from old.project_id
     or new.lang is distinct from old.lang
     or new.source_text is distinct from old.source_text
     or new.status is distinct from old.status then
    raise exception 'segments are immutable';
  end if;

  if new.target_text is distinct from old.target_text then
    if new.status = 'reviewed' then
      raise exception 'only reviewers may mark segments reviewed';
    end if;

    if not public.is_translator(new.project_id, new.lang) then
      raise exception 'not assigned to this language';
    end if;

    new.translated_by := auth.uid();
  end if;

  return new;
end;
$$;

