create or replace function public.sign_envelope(p_envelope_id bigint)
returns text
language plpgsql
security definer
set search_path = public
as $$
declare
  v_envelope public.envelopes%rowtype;
  v_signer uuid := auth.uid();
  v_order integer;
  v_earliest_unsigned integer;
begin
  if v_signer is null then
    raise exception 'not authenticated';
  end if;

  select * into v_envelope
  from public.envelopes
  where id = p_envelope_id
  for update;

  if not found or v_envelope.status <> 'sent' then
    raise exception 'envelope is not signed';
  end if;

  if v_envelope.sender_id = v_signer then
    raise exception 'sender cannot sign';
  end if;

  select sign_order into v_order
  from public.envelope_recipients
  where envelope_id = p_envelope_id and user_id = v_signer;

  if v_order is null then
    raise exception 'not a recipient';
  end if;

  if v_envelope.sender_id = v_signer then
    raise exception 'sender cannot sign';
  end if;

  update public.envelope_recipients
  set signed_at = now()
  where envelope_id = p_envelope_id and user_id = v_signer;

  select count(*) into v_earliest_unsigned
  from public.envelope_recipients
  where envelope_id = p_envelope_id and signed_at is null;

  if v_earliest_unsigned > 0 then
    return 'sent';
  end if;

  update public.envelopes
  set status = 'completed'
  where id = p_envelope_id;

  return 'completed';
end;
$$;

create or replace function public.void_envelope(p_envelope_id bigint)
returns text
language plpgsql
security definer
set search_path = public
as $$
declare
  v_envelope public.envelopes%rowtype;
  v_signer uuid := auth.uid();
begin
  if v_signer is null then
    raise exception 'not authenticated';
  end if;

  select * into v_envelope
  from public.envelopes
  where id = p_envelope_id
  for update;

  if not found then
    raise exception 'envelope not found';
  end if;

  if v_envelope.sender_id <> v_signer then
    raise exception 'only the sender can void';
  end if;

  if v_envelope.status <> 'sent' then
    raise exception 'envelope is not sent';
  end if;

  update public.envelopes
  set status = 'voided'
  where id = p_envelope_id;

  return 'voided';
end;
$$;

