  )
$$;

create function private.envelope_signer_before(p_envelope_id bigint, p_user_id uuid, p_sign_order integer) returns boolean
language sql stable security definer set search_path = ''
as $$
  select exists (
    select 1 from public.envelope_recipients r
    where r.envelope_id = p_envelope_id
      and r.user_id <> p_user_id
      and r.sign_order < p_sign_order
      and r.signed_at is null
  )
$$;

create function public.sign_envelope(p_envelope_id bigint) returns text
language plpgsql security definer set search_path = ''
as $$
declare
  v_uid uuid := auth.uid();
  v_status text;
begin
  if v_uid is null then
    raise exception 'not authenticated';
  end if;

  if not private.is_envelope_recipient(p_envelope_id) then
    raise exception 'not a recipient';
  end if;

  if private.envelope_signer_before(p_envelope_id, v_uid, (select sign_order from public.envelope_recipients where envelope_id = p_envelope_id and user_id = v_uid)) then
    raise exception 'an earlier recipient has not signed yet';
  end if;

  if exists (select 1 from public.envelope_recipients where envelope_id = p_envelope_id and user_id = v_uid and signed_at is not null) then
    raise exception 'already signed';
  end if;

  update public.envelope_recipients
  set signed_at = now()
  where envelope_id = p_envelope_id and user_id = v_uid;

  select e.status into v_status
  from public.envelopes e
  where e.id = p_envelope_id;

  if not exists (
    select 1 from public.envelope_recipients r
    where r.envelope_id = p_envelope_id and r.signed_at is null
  ) then
    update public.envelopes
    set status = 'completed'
    where id = p_envelope_id and status = 'sent';
  end if;

  return v_status;
end
$$;

create function public.void_envelope(p_envelope_id bigint) returns text
language plpgsql security definer set search_path = ''
as $$
declare
  v_uid uuid := auth.uid();
  v_status text;
begin
  if v_uid is null then
    raise exception 'not authenticated';
  end if;

  select e.status, e.sender_id into v_status, v_uid
  from public.envelopes e
  where e.id = p_envelope_id
  for update;

  if v_status is null then
    raise exception 'envelope not found';
  end if;

  if v_status <> 'sent' then
    raise exception 'envelope is not sent';
  end if;

  if v_uid <> auth.uid() then
    raise exception 'only the sender can void this envelope';
  end if;

  update public.envelopes
  set status = 'voided'
  where id = p_envelope_id and status = 'sent'
  returning status into v_status;

  return v_status;
end
$$;

