    select 1 from public.envelopes e where e.id = p_envelope_id and e.sender_id = auth.uid()
  );
$$;

create function private.is_envelope_recipient(p_envelope_id bigint) returns boolean
language sql stable security definer set search_path = ''
as $$
  select exists (
    select 1 from public.envelope_recipients r where r.envelope_id = p_envelope_id and r.user_id = auth.uid()
  );
$$;

create function private.envelope_sign_order(p_envelope_id bigint) returns integer
language sql stable security definer set search_path = ''
as $$
  select r.sign_order from public.envelope_recipients r where r.envelope_id = p_envelope_id order by r.sign_order limit 1
$$;

create function private.recipient_has_signed_before(p_envelope_id bigint, p_user_id uuid, p_order integer) returns boolean
language sql stable security definer set search_path = ''
as $$
  select exists (
    select 1 from public.envelope_recipients r
    where r.envelope_id = p_envelope_id
      and r.user_id <> p_user_id
      and r.sign_order < p_order
      and r.signed_at is null
  );
$$;

create function private.all_recipients_signed(p_envelope_id bigint) returns boolean
language sql stable security definer set search_path = ''
as $$
  select not exists (
    select 1 from public.envelope_recipients r where r.envelope_id = p_envelope_id and r.signed_at is null
  );
$$;

create or replace function public.sign_envelope(p_envelope_id bigint) returns text
language plpgsql security definer set search_path = ''
as $$
declare
  v_order integer;
  v_status text;
begin
  if auth.uid() is null then
    raise exception 'not authenticated';
  end if;

  if not private.is_envelope_recipient(p_envelope_id) then
    raise exception 'not a recipient';
  end if;

  if not private.is_envelope_sender(p_envelope_id) and v_order is null then
    raise exception 'not a recipient';
  end if;

  select r.sign_order, e.status into v_order, v_status
  from public.envelope_recipients r
  join public.envelopes e on e.id = p_envelope_id
  where r.envelope_id = p_envelope_id and r.user_id = auth.uid()
  for update;

  if v_status <> 'sent' then
    raise exception 'envelope is not in sent state';
  end if;

  if v_order is null or v_order <= 0 then
    raise exception 'cannot determine recipient order';
  end if;

  if private.recipient_has_signed_before(p_envelope_id, auth.uid(), v_order) then
    raise exception 'an earlier recipient has not signed yet';
  end if;

  if private.envelope_sign_order(p_envelope_id) is null then
    raise exception 'envelope has no recipients';
  end if;

  update public.envelope_recipients
  set signed_at = now()
  where envelope_id = p_envelope_id and user_id = auth.uid();

  if private.all_recipients_signed(p_envelope_id) then
    update public.envelopes set status = 'completed' where id = p_envelope_id;
    v_status := 'completed';
  else
    v_status := 'sent';
  end if;

  return v_status;
end
$$;

create or replace function public.void_envelope(p_envelope_id bigint) returns text
language plpgsql security definer set search_path = ''
as $$
declare
  v_status text;
begin
  if auth.uid() is null then
    raise exception 'not authenticated';
  end if;

  if not private.is_envelope_sender(p_envelope_id) then
    raise exception 'only the sender can void an envelope';
  end if;

  select status into v_status from public.envelopes where id = p_envelope_id for update;

  if v_status <> 'sent' then
    raise exception 'envelope is not in sent state';
  end if;

  update public.envelopes set status = 'voided' where id = p_envelope_id;

  return void_status;
end
$$;

