  select r.sign_order from public.envelope_recipients r where r.envelope_id = p_envelope_id order by r.sign_order limit 1
$$;

create function private.recipient_has_signed_before(p_envelope_id bigint, p_user_id uuid, p_order integer) returns boolean
language sql stable security definer set search_path = ''
as $$
  select exists (
    select 1 from public.envelope_recipients r
    where r.envelope_id = p_envelope_id
      and r.user_id <> p_user_id
      and r.sign_order < p_order
      and r.signed_at is null
  );
$$;

create function private.all_recipients_signed(p_envelope_id bigint) returns boolean
language sql stable security definer set search_path = ''
as $$
  select not exists (
    select 1 from public.envelope_recipients r where r.envelope_id = p_envelope_id and r.signed_at is null
  );
$$;

create function public.sign_envelope(p_envelope_id bigint) returns text
language plpgsql security definer set search_path = ''
as $$
declare
  v_uid uuid := auth.uid();
  v_status text;
begin
  if v_uid is null then
    raise exception 'not authenticated';
  end if;

  if not private.is_envelope_recipient(p_envelope_id) then
    raise exception 'not a recipient';
  end if;

  if private.envelope_sign_order(p_envelope_id) is null then
    raise exception 'envelope has no recipients';
  end if;

  if private.recipient_has_signed_before(p_envelope_id, v_uid, (select r.sign_order from public.envelope_recipients r where r.envelope_id = p_envelope_id and r.user_id = v_uid)) then
    raise exception 'an earlier recipient has not signed';
  end if;

  if not private.all_recipients_signed(p_envelope_id) then
    raise exception 'envelope is not sent';
  end if;

  update public.envelope_recipients
     set signed_at = now()
   where envelope_id = p_envelope_id
     and user_id = v_uid;

  update public.envelopes
     set status = 'completed'
   where id = p_envelope_id;

  select status into v_status from public.envelopes where id = p_envelope_id;
  return v_status;
end
$$;

create function public.void_envelope(p_envelope_id bigint) returns text
language plpgsql security definer set search_path = ''
as $$
declare
  v_uid uuid := auth.uid();
  v_status text;
begin
  if v_uid is null then
    raise exception 'not authenticated';
  end if;

  if not private.is_envelope_sender(p_envelope_id) then
    raise exception 'not a sender';
  end if;

  update public.envelopes
     set status = 'voided'
   where id = p_envelope_id
     and status = 'sent';

  get diagnostics v_status = row_count;

  if v_status = 0 then
    raise exception 'envelope is not sent';
  end if;

  return 'voided';
end
$$;

