language sql stable security definer set search_path = ''
as $$
  select exists (
    select 1 from public.envelope_recipients r
    where r.envelope_id = p_envelope_id
      and r.user_id = auth.uid()
  )
$$;

create function private.envelope_signer(p_envelope_id bigint) returns uuid
language sql stable security definer set search_path = ''
as $$
  select r.user_id from public.envelope_recipients r
  where r.envelope_id = p_envelope_id
  order by r.sign_order
  limit 1
$$;

create function private.envelope_signed_before(p_envelope_id bigint, p_user_id uuid) returns boolean
language sql stable security definer set search_path = ''
as $$
  select exists (
    select 1 from public.envelope_recipients r
    where r.envelope_id = p_envelope_id
      and r.sign_order < (select r2.sign_order from public.envelope_recipients r2 where r2.envelope_id = p_envelope_id and r2.user_id = p_user_id)
      and r2.signed_at is not null
  )
$$;

create function private.envelope_all_signed(p_envelope_id bigint) returns boolean
language sql stable security definer set search_path = ''
as $$
  select not exists (
    select 1 from public.envelope_recipients r
    where r.envelope_id = p_envelope_id
      and r.signed_at is null
  )
$$;

