create function public.sign_envelope(p_envelope_id bigint) returns text
language plpgsql security definer set search_path = ''
as $$
declare
  v_status text;
  v_signer uuid := auth.uid();
begin
  if v_signer is null then
    raise exception 'Authentication required';
  end if;

  select e.status into v_status
  from public.envelopes e
  where e.id = p_envelope_id
  for update;

  if not found then
    raise exception 'Envelope not found';
  end if;

  if v_status <> 'sent' then
    raise exception 'Envelope cannot be signed in status %', v_status;
  end if;

  if private.envelope_signer(p_envelope_id) <> v_signer then
    raise exception 'Only the next signer in order may sign';
  end if;

  if private.envelope_signed_before(p_envelope_id, v_signer) then
    raise exception 'Earlier recipient has not signed yet';
  end if;

  if private.envelope_recipients(p_envelope_id, v_signer) is not null then
    raise exception 'Already signed';
  end if;

  update public.envelope_recipients
  set signed_at = now()
  where envelope_id = p_envelope_id
    and user_id = v_signer;

  if private.envelope_all_signed(p_envelope_id) then
    update public.envelopes
    set status = 'completed'
    where id = p_envelope_id;
  end if;

  select e.status into v_status
  from public.envelopes e
  where e.id = p_envelope_id;

  return v_status;
end
$$;

create function public.void_envelope(p_envelope_id bigint) returns text
language plpgsql security definer set search_path = ''
as $$
declare
  v_signer uuid := auth.uid();
  v_status text;
begin
  if v_signer is null then
    raise exception 'Authentication required';
  end if;

  select e.status into v_status
  from public.envelopes e
  where e.id = p_envelope_id
  for update;

  if not found then
    raise exception 'Envelope not found';
  end if;

  if v_status <> 'sent' then
    raise exception 'Envelope cannot be voided in status %', v_status;
  end if;

  if private.is_envelope_recipient(p_envelope_id) then
    raise exception 'Recipients cannot void envelopes';
  end if;

  update public.envelopes
  set status = 'voided'
  where id = p_envelope_id;

  select e.status into v_status
  from public.envelopes e
  where e.id = p_envelope_id;

  return v_status;
end
$$;
