create or replace function public.proposals_guard()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  if new.speaker_id is distinct from auth.uid() then
    raise exception 'proposals.speaker_id must be the current user';
  end if;
  if new.status is distinct from 'submitted' then
    raise exception 'proposals.status must be submitted';
  end if;
  return new;
end;
$$;

create or replace function public.reviews_guard()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
declare
  v_proposal_status text;
begin
  if new.reviewer_id is distinct from auth.uid() then
    raise exception 'reviews.reviewer_id must be the current user';
  end if;

  if new.proposal_id is not null then
    select p.status into v_proposal_status
    from public.proposals p
    where p.id = new.proposal_id
    for update;

    if not found then
      raise exception 'proposal % does not exist', new.proposal_id;
    end if;

    if v_proposal_status <> 'submitted' then
      raise exception 'reviews can only be submitted for undecided proposals';
    end if;

    if public.reviewer_own_proposal(new.proposal_id) then
      raise exception 'reviewers cannot review their own proposals';
    end if;

    if public.review_own_review(new.proposal_id) then
      raise exception 'reviewers can only submit one review per proposal';
    end if;
  end if;

  return new;
end;
$$;

